contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address _recipient) public payable {
        require(address(this).balance > 0);
        require(_recipient != address(0));

        address payable target = payable(_recipient);
        uint256 cBalanceBefore = address(c).balance;
        uint256 recipientBefore = target.balance;

        bool reverted;
        try c.withdrawAll(_recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 received = target.balance - recipientBefore;

        assert(
            (!reverted && address(c).balance == 0 && received == cBalanceBefore) ||
            (reverted && address(c).balance == cBalanceBefore && received == 0)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address recipient, address caller) public payable {
        // Make the test contract hold some Ether, then force it into c.
        require(address(this).balance >= 1);
        (bool funded, ) = address(c).call{value: 1}();
        require(funded);

        uint256 balBefore = address(c).balance;

        // Only the owner may call withdrawAll; everyone else must be rejected.
        bool reverted;
        if (caller == c.owner()) {
            reverted = true;
        } else {
            (bool ok, ) = address(c).call(
                abi.encodeWithSignature("withdrawAll(address)", recipient)
            );
            reverted = !ok;
        }

        assert(reverted && address(c).balance == balBefore);
    }

    receive() external payable {}
}

